}
#else
// 非 aarch64：无 ADCS 指令，用软件 128 位加法模拟（结果与黄金一致）
static void adcx_chain_correct(const uint64_t *lhs, const uint64_t *rhs,
                               uint64_t *result, size_t n, uint64_t carry_in) {
    for (size_t i = 0; i < n; ++i) {
