/**
 * @file adcx.cpp
 * @copyright SPDX-License-Identifier: Apache-2.0
 *
 * @test adcx
 * @parblock
 * Testing unsigned add with carry on ARM64 using ADCS instruction sequence.
 * Validates multi-precision addition and carry propagation on ARMv8/v9 processors.
 * @endparblock
