46	static constexpr size_t MIN_BLOCK = 64;            /* one cache line */
47	static constexpr size_t MAX_BLOCK = 2u << 20;      /* 2 MiB */
48	static constexpr size_t DEFAULT_SIZE_FLOOR = 8u << 20;    /* 8 MiB */
49	static constexpr size_t DEFAULT_SIZE_CAP  = 512u << 20;   /* 512 MiB */
50	
51	enum AddrMode  { ADDR_RAND, ADDR_SEQ };
52	enum ValMode   { VAL_RANDOM, VAL_PATTERN, VAL_SPECIALS };
