54	/* One region PER CPU: test_run executes concurrently on every worker
55	 * thread sharing the same test->data, so a single region would race
56	 * (fill/transform from two threads on overlapping blocks — observed as
57	 * immediate multi-thread failures). Same per-cpu pattern as
58	 * fisttp_arm's thread_ctx. */
59	struct RegionInfo {
60	    uint8_t *base;
61	    size_t   size;
62	};
63	
64	struct SweepData {
65	    std::vector<RegionInfo> regions;   /* one per cpu */
66	    size_t region_size;                /* common size */
67	};
