69	/* High-Hamming value table (same construction as lsu_store_forward_arm /
70	 * operand_space_arm: successive entries maximise data-path gate toggling).
71	 */
72	static const uint64_t SPECIALS_TABLE[] = {
73	    0x0000000000000000ULL, 0xFFFFFFFFFFFFFFFFULL,
74	    0xAAAAAAAAAAAAAAAAULL, 0x5555555555555555ULL,
75	    0x0F0F0F0F0F0F0F0FULL, 0xF0F0F0F0F0F0F0F0ULL,
76	    0x123456789ABCDEF0ULL, 0xFEDCBA9876543210ULL,
77	};
78	
79	/* Read MemAvailable from /proc/meminfo, in KiB; -1 if unreadable.
80	 * (Same helper shape as memcpy_rewr.cpp.)
81	 */
82	static long read_mem_available_kib(void)
83	{
84	    FILE *f = fopen("/proc/meminfo", "r");
85	    if (!f)
86	        return -1;
87	    long val = -1;
88	    char key[64];
89	    while (fscanf(f, "%63s %ld", key, &val) == 2) {
90	        if (strcmp(key, "MemAvailable:") == 0)
91	            break;
92	        val = -1;
93	        int c;
94	        while ((c = fgetc(f)) != EOF && c != '\n')
95	            ;
96	    }
97	    fclose(f);
98	    return val;
99	}
100	
101	/* Memory-adaptive per-thread region size: 60% of MemAvailable split over
102	 * the worker threads, capped at 512 MiB, floored at 8 MiB. The 0.6
103	 * factor leaves headroom for the framework, the golden recompute and
104	 * the page cache (same conservative reasoning as svd_cdouble_sve's
105	 * per-worker RAM budget).
106	 */
107	static size_t default_region_bytes(void)
108	{
109	    long kib = read_mem_available_kib();
110	    if (kib <= 0)
111	        return DEFAULT_SIZE_FLOOR;
112	    int threads = thread_count();
113	    if (threads <= 0)
114	        threads = 1;
115	    double per_thread = (double)kib * 1024.0 * 0.6 / threads;
116	    size_t s = (size_t)per_thread;
117	    if (s > DEFAULT_SIZE_CAP)  s = DEFAULT_SIZE_CAP;
118	    if (s < DEFAULT_SIZE_FLOOR) s = DEFAULT_SIZE_FLOOR;
119	    return s;
