138	 * block[i] ^= rotl64(block[i] + K, 13)  — per 128-bit vector: a
139	 * load, an integer add, a rotate, a xor and a store, so both the LSU
140	 * and the vector ALU participate. The scalar golden below repeats the
141	 * SAME arithmetic independently (different instruction path).
142	 */
143	static constexpr uint64_t TWEAK_K = 0x9E3779B97F4A7C15ULL;
144	
145	#ifdef __aarch64__
146	static void transform_block_neon(uint8_t *p, size_t len)
147	{
148	    const uint64x2_t vk = vdupq_n_u64(TWEAK_K);
149	    uint64_t *w = reinterpret_cast<uint64_t *>(p);
150	    size_t vec_count = len / 16;
151	    for (size_t i = 0; i < vec_count; ++i) {
152	        uint64x2_t v = vld1q_u64(&w[2 * i]);
153	        uint64x2_t t = vaddq_u64(v, vk);
154	        /* rotate each lane left by 13: t = (t << 13) | (t >> 51) */
155	        uint64x2_t sh  = vshlq_n_u64(t, 13);
156	        uint64x2_t shr = vshrq_n_u64(t, 51);
157	        uint64x2_t rot = vorrq_u64(sh, shr);
158	        vst1q_u64(&w[2 * i], veorq_u64(v, rot));
159	    }
160	}
161	#endif
