10	// 获取 L3 缓存大小（字节），若失败则使用默认 8MB
11	static size_t get_l3_size() {
12	    long size = sysconf(_SC_LEVEL3_CACHE_SIZE);
13	    if (size > 0) return static_cast<size_t>(size);
14	    // 常见 L3 缓存大小：8MB
15	    return 8 * 1024 * 1024;
16	}
17	
18	static const size_t BLOCK_SIZE = get_l3_size();
19	
20	static int memcpy_l3_cache_size_init(struct test *test) {
21	    (void)test;
22	    return EXIT_SUCCESS;
23	}
24	
25	static int memcpy_l3_cache_size_run(struct test *test, int cpu) {
26	    (void)cpu;
27	
28	    std::vector<uint8_t> src(BLOCK_SIZE);
29	    std::vector<uint8_t> dst(BLOCK_SIZE);
30	
31	    // 随机数生成器（每个线程独立）
32	    std::mt19937 rng(std::random_device{}());
33	    std::uniform_int_distribution<uint8_t> dist(0, 255);
34	
35	    static std::atomic<uint64_t> iter{0};
36	
37	    do {
38	        // 填充源数据为随机字节（SIMD 风格数据本质上就是随机字节）
39	        for (size_t i = 0; i < BLOCK_SIZE; ++i) {
40	            src[i] = dist(rng);
41	        }
42	
43	        // 执行内存复制
44	        memcpy(dst.data(), src.data(), BLOCK_SIZE);
45	
46	        // 验证数据是否完全一致
47	        bool data_ok = (memcmp(dst.data(), src.data(), BLOCK_SIZE) == 0);
48	
