        sd->seq.fetch_add(1, std::memory_order_acq_rel);

        // 读操作：使用非对齐加载（vld1q_u8 支持非对齐地址）
        uint64_t s1, s2;
        uint8x16_t read_val;
        do {
            s1 = sd->seq.load(std::memory_order_acquire);
            read_val = vld1q_u8((uint8_t*)&sd->data);   // 非对齐加载
            s2 = sd->seq.load(std::memory_order_acquire);
        } while (s1 != s2 || (s1 & 1));

